# >>> CHOICES
if [[ -n "$ARGC_COMPLETIONS_ROOT" && -f "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh" ]]; then
    . "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh"
fi

_choice_vercel_deployment() {
    local scope="${argc_scope:-}" project="${argc_project:-${argc_app:-}}"
    if [[ -n "${ARGC_COMPLETIONS_ROOT:-}" ]]; then
        _argc_util_cache 120 _helper_vercel_deployments_uncached "vercel_deployments_${scope:-default}_${project:-default}"
    else
        _helper_vercel_deployments_uncached
    fi
}

_choice_vercel_environment() {
    if [[ -n "${ARGC_COMPLETIONS_ROOT:-}" ]]; then
        _argc_util_cache 300 _helper_vercel_environments_uncached "vercel_environments"
    else
        _helper_vercel_environments_uncached
    fi
}

_choice_vercel_project() {
    local scope="${argc_scope:-}"
    if [[ -n "${ARGC_COMPLETIONS_ROOT:-}" ]]; then
        _argc_util_cache 300 _helper_vercel_projects_uncached "vercel_projects_${scope:-default}"
    else
        _helper_vercel_projects_uncached
    fi
}

_choice_vercel_team() {
    if [[ -n "${ARGC_COMPLETIONS_ROOT:-}" ]]; then
        _argc_util_cache 300 _helper_vercel_teams_uncached "vercel_teams"
    else
        _helper_vercel_teams_uncached
    fi
}

_helper_vercel_deployments_uncached() {
    _helper_vercel_ready || return 0
    local project="${argc_project:-${argc_app:-}}"
    local -a q=(list)
    [[ -n "$project" ]] && q+=("$project")
    _helper_vercel_query "${q[@]}" | _helper_vercel_json_values 'url,id,name' | head -n 50
}

_helper_vercel_environments_uncached() {
    _helper_vercel_ready || return 0
    printf '%s\n' production preview
    _helper_vercel_query environments list | _helper_vercel_json_values 'name,slug,id' | head -n 50
}

_helper_vercel_json_values() {
    local order="$1"
    jq -b -r --arg order "$order" '
        def fields: $order | split(",");
        def pick: . as $o | [fields[] | $o[.]] | map(select(. != null and . != "")) | .[0] // empty;
        def rows:
          if type == "array" then .[]
          elif type == "object" then
            (if .projects != null then (.projects | if type=="array" then .[] else . end)
             elif .teams != null then (.teams | if type=="array" then .[] else . end)
             elif .deployments != null then (.deployments | if type=="array" then .[] else . end)
             elif .environments != null then (.environments | if type=="array" then .[] else . end)
             elif .data != null then (.data | if type=="array" then .[] else . end)
             elif .items != null then (.items | if type=="array" then .[] else . end)
             elif .results != null then (.results | if type=="array" then .[] else . end)
             else . end)
          else empty end;
        rows
        | if type == "string" then .
          elif type == "object" then pick
          else empty end
        | tostring | select(length > 0)
    ' 2>/dev/null
}

_helper_vercel_projects_uncached() {
    _helper_vercel_ready || return 0
    _helper_vercel_query project list | _helper_vercel_json_values 'name,slug,id' | head -n 100
}

_helper_vercel_query() {
    local -a cmd=(vercel)
    local scope="${argc_scope:-}"
    [[ -n "$scope" ]] && cmd+=(-S "$scope")
    cmd+=("$@" --json)
    "${cmd[@]}" 2>/dev/null
}

_helper_vercel_ready() {
    # Quick, non-interactive auth probe: never starts a login flow.
    vercel whoami --non-interactive >/dev/null 2>&1
}

_helper_vercel_teams_uncached() {
    _helper_vercel_ready || return 0
    _helper_vercel_query teams list | _helper_vercel_json_values 'slug,name' | head -n 50
}
# <<< CHOICES

command eval "$(argc --argc-eval "$0" "$@")"
